#include "phase6_test.hpp"
#include "control/supervisor.hpp"
namespace{struct Context{std::atomic<unsigned>polls{0};};control::SupervisorInputs read(void*p)noexcept{static_cast<Context*>(p)->polls.fetch_add(1,std::memory_order_relaxed);return {true,false,true,control::Intent::none};}}
int main(){Phase6Test t;control::Supervisor s;t.check(control::Supervisor::period_ns==100000000ULL,"exact 100ms nominal period");t.check(std::atomic<bool>::is_always_lock_free,"lock free relaxed atomic flags");t.check(s.halted(),"startup closed");s.poll({true,false,true,control::Intent::none});t.check(!s.halted()&&!s.pause(),"healthy");s.poll({false,false,true,control::Intent::none});t.check(s.halted()&&s.lock_failed(),"lock propagation");s.poll({true,true,true,control::Intent::none});t.check(s.halted()&&s.kill(),"kill file propagation");s.poll({true,false,false,control::Intent::none});t.check(s.halted()&&s.disk_failed(),"disk propagation");s.poll({true,false,true,control::Intent::pause});t.check(!s.halted()&&s.pause()&&!s.flatten(),"pause intent");s.poll({true,false,true,control::Intent::flatten});t.check(s.pause()&&s.flatten(),"flatten intent");s.poll({true,false,true,control::Intent::kill});t.check(s.halted()&&s.pause()&&s.flatten(),"kill intent");Context c;control::SupervisorThread loop(s,read,&c);t.check(loop.start(),"thread start");t.check(!loop.start(),"single thread");std::this_thread::sleep_for(std::chrono::milliseconds(250));loop.stop();auto first=c.polls.load();t.check(first>=3&&first<=4,"10Hz schedule");t.check(!loop.running(),"clean shutdown");t.check(loop.start(),"restart");std::this_thread::sleep_for(std::chrono::milliseconds(20));loop.stop();t.check(c.polls.load()>first,"poll after restart");return t.result();}
